record.field:
action = False


def toast(title, message, kind='warning', sticky=False, next_action=False):
    params = {'title': title, 'message': message, 'type': kind, 'sticky': sticky}
    if next_action:
        params['next'] = next_action
    return {'type': 'ir.actions.client', 'tag': 'display_notification', 'params': params}


def reload_applicant(applicant):
    title = applicant.partner_name or applicant.display_name or 'Applicant'
    return {
        'type': 'ir.actions.act_window',
        'name': title,
        'res_model': 'hr.applicant',
        'res_id': applicant.id,
        'view_mode': 'form',
        'views': [(False, 'form')],
        'target': 'current',
    }


def write_handover(applicant, state, ready, notes):
    vals = {}
    mapping = {
        'x_employment_handover_state': state,
        'x_employment_handover_ready': bool(ready),
        'x_employment_handover_checked_on': datetime.datetime.now(),
        'x_employment_handover_checked_by_user_id': env.user.id,
        'x_employment_handover_notes': notes or False,
    }
    for field_name, value in mapping.items():
        if field_name in applicant._fields:
            vals[field_name] = value
    if vals:
        applicant.write(vals)


def write_payroll_status(applicant, ready, notes):
    vals = {}
    mapping = {
        'x_employment_payroll_ready': bool(ready),
        'x_employment_payroll_checked_on': datetime.datetime.now(),
        'x_employment_payroll_checked_by_user_id': env.user.id,
        'x_employment_payroll_notes': notes or False,
    }
    for field_name, value in mapping.items():
        if field_name in applicant._fields:
            vals[field_name] = value
    if vals:
        applicant.write(vals)


def first_value(record, field_names):
    if not record:
        return False
    record_fields = record._fields
    for field_name in field_names:
        if field_name in record_fields and record[field_name]:
            return record[field_name]
    return False


def get_pool_from_applicant(applicant):
    if 'x_pool_id' in applicant._fields and applicant.x_pool_id:
        return applicant.x_pool_id.sudo()
    return False


def get_source_employment_contract(applicant):
    if 'x_employment_contract_id' in applicant._fields and applicant.x_employment_contract_id:
        return applicant.x_employment_contract_id.sudo()
    ContractCockpit = env['x_hr.applicant_employment_contract'].sudo()
    return ContractCockpit.search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', 'in', ['signed_uploaded', 'ministry_accredited']),
    ], order='id desc', limit=1)


def selection_contains(model, field_name, key):
    if field_name not in model._fields:
        return False
    selection = model._fields[field_name].selection or []
    try:
        keys = [item[0] for item in selection]
    except Exception:
        keys = []
    return key in keys


def find_first(model_name, domains):
    try:
        model = env[model_name].sudo()
    except Exception:
        return False
    for domain in domains:
        rec = model.search(domain, limit=1)
        if rec:
            return rec
    return False


def compute_employee_vals(applicant, employee=False):
    Employee = env['hr.employee'].sudo()
    employee_fields = Employee._fields
    applicant_fields = applicant._fields
    pool = get_pool_from_applicant(applicant)

    vals = {}

    employee_name = applicant.partner_name or applicant.display_name or applicant.name or 'New Employee'
    if 'name' in employee_fields:
        vals['name'] = employee_name

    if 'x_source_applicant_id' in employee_fields:
        vals['x_source_applicant_id'] = applicant.id
    if 'x_employment_handover_on' in employee_fields:
        vals['x_employment_handover_on'] = datetime.datetime.now()
    if 'x_employment_handover_by_user_id' in employee_fields:
        vals['x_employment_handover_by_user_id'] = env.user.id

    if 'image_1920' in employee_fields and 'x_profile_photo_1920' in applicant_fields and applicant.x_profile_photo_1920:
        if not employee or not employee.image_1920:
            vals['image_1920'] = applicant.x_profile_photo_1920

    if 'job_id' in employee_fields and 'job_id' in applicant_fields and applicant.job_id:
        vals['job_id'] = applicant.job_id.id

    department = False
    if 'department_id' in applicant_fields and applicant.department_id:
        department = applicant.department_id
    elif 'x_department_id' in applicant_fields and applicant.x_department_id:
        department = applicant.x_department_id
    elif 'job_id' in applicant_fields and applicant.job_id and 'department_id' in applicant.job_id._fields and applicant.job_id.department_id:
        department = applicant.job_id.department_id

    if department and 'department_id' in employee_fields:
        vals['department_id'] = department.id

    if department and 'parent_id' in employee_fields and 'manager_id' in department._fields and department.manager_id:
        if not employee or employee.id != department.manager_id.id:
            vals['parent_id'] = department.manager_id.id

    if 'job_title' in employee_fields:
        job_title = False
        if 'x_tor_job_title' in applicant_fields and applicant.x_tor_job_title:
            job_title = applicant.x_tor_job_title
        elif 'job_id' in applicant_fields and applicant.job_id:
            job_title = applicant.job_id.name
        if job_title:
            vals['job_title'] = job_title

    email_value = first_value(pool, ['x_email', 'email', 'email_from']) or first_value(applicant, [
        'email_from',
        'x_email',
        'x_personal_email',
        'email_cc',
    ])
    if email_value:
        if 'work_email' in employee_fields:
            vals['work_email'] = email_value
        if 'private_email' in employee_fields:
            vals['private_email'] = email_value

    phone_value = first_value(pool, ['x_phone', 'x_mobile', 'phone', 'mobile']) or first_value(applicant, [
        'partner_mobile',
        'x_mobile',
        'x_phone',
        'x_work_phone',
        'partner_phone',
    ])
    if phone_value:
        if 'work_phone' in employee_fields:
            vals['work_phone'] = phone_value
        if 'mobile_phone' in employee_fields:
            vals['mobile_phone'] = phone_value
        if 'work_mobile' in employee_fields:
            vals['work_mobile'] = phone_value
        if 'private_phone' in employee_fields:
            vals['private_phone'] = phone_value

    national_id_value = first_value(applicant, [
        'x_national_id',
        'x_national_id_number',
        'x_identity_number',
        'x_applicant_national_id',
    ]) or first_value(pool, ['x_national_id'])

    if national_id_value and 'identification_id' in employee_fields:
        vals['identification_id'] = national_id_value

    return vals, national_id_value


def prepare_applicant_payroll_defaults(applicant):
    """Populate editable applicant handover defaults before writing employee Payroll tab fields.

    Source precedence:
    F-0005 cockpit values
    → existing applicant employment contract fields
    → applicant availability/defaults
    → safe payroll defaults.
    """
    applicant_fields = applicant._fields
    source_contract = get_source_employment_contract(applicant)
    vals = {}

    source_start = False
    source_end = False
    source_wage = False

    if source_contract:
        sc_fields = source_contract._fields
        if 'x_contract_start_date' in sc_fields and source_contract.x_contract_start_date:
            source_start = source_contract.x_contract_start_date
        if 'x_contract_end_date' in sc_fields and source_contract.x_contract_end_date:
            source_end = source_contract.x_contract_end_date
        if 'x_monthly_wage_amount' in sc_fields and source_contract.x_monthly_wage_amount:
            source_wage = source_contract.x_monthly_wage_amount

    if not source_start and 'x_employment_contract_start_date' in applicant_fields and applicant.x_employment_contract_start_date:
        source_start = applicant.x_employment_contract_start_date
    if not source_start and 'availability' in applicant_fields and applicant.availability:
        source_start = applicant.availability

    if not source_end and 'x_employment_contract_end_date' in applicant_fields and applicant.x_employment_contract_end_date:
        source_end = applicant.x_employment_contract_end_date

    if not source_wage and 'x_employment_contract_monthly_wage' in applicant_fields and applicant.x_employment_contract_monthly_wage:
        source_wage = applicant.x_employment_contract_monthly_wage

    # F-0005/applicant contract dates and wage are the authoritative handover snapshot
    # values and should be written to the editable handover fields before payroll sync.
    if 'x_handover_contract_date_start' in applicant_fields and source_start:
        if applicant.x_handover_contract_date_start != source_start:
            vals['x_handover_contract_date_start'] = source_start

    if 'x_handover_contract_date_end' in applicant_fields and source_end:
        if applicant.x_handover_contract_date_end != source_end:
            vals['x_handover_contract_date_end'] = source_end

    if 'x_handover_wage' in applicant_fields and source_wage:
        if applicant.x_handover_wage != source_wage:
            vals['x_handover_wage'] = source_wage

    # Operational defaults: write only when empty so HR can manually override.
    if 'x_handover_wage_type' in applicant_fields and not applicant.x_handover_wage_type:
        vals['x_handover_wage_type'] = 'monthly'

    if 'x_handover_work_entry_source' in applicant_fields and not applicant.x_handover_work_entry_source:
        vals['x_handover_work_entry_source'] = 'calendar'

    if 'x_handover_resource_calendar_id' in applicant_fields and not applicant.x_handover_resource_calendar_id:
        resource_calendar = find_first('resource.calendar', [
            [('name', '=', 'Standard 40 hours/week'), ('company_id', 'in', [env.company.id, False])],
            [('name', 'ilike', 'Standard 40'), ('company_id', 'in', [env.company.id, False])],
            [('company_id', 'in', [env.company.id, False])],
            [],
        ])
        if resource_calendar:
            vals['x_handover_resource_calendar_id'] = resource_calendar.id

    if 'x_handover_contract_type_id' in applicant_fields and not applicant.x_handover_contract_type_id:
        contract_type = find_first('hr.contract.type', [
            [('name', '=', 'Employee')],
            [('name', '=', 'Full-Time')],
            [('name', '=', 'Permanent')],
            [],
        ])
        if contract_type:
            vals['x_handover_contract_type_id'] = contract_type.id

    if 'x_handover_structure_type_id' in applicant_fields and not applicant.x_handover_structure_type_id:
        structure_type = find_first('hr.payroll.structure.type', [
            [('name', '=', 'Fixed Month - Regular')],
            [('name', 'ilike', 'Fixed Month')],
            [('name', '=', 'Employee')],
            [],
        ])
        if structure_type:
            vals['x_handover_structure_type_id'] = structure_type.id

    if vals:
        applicant.write(vals)
        applicant.message_post(
            body='تم تحديث إعدادات الرواتب الافتراضية للترحيل من بيانات العقد/المتقدم والقيم الافتراضية الآمنة: %s.'
            % ', '.join(sorted(vals.keys()))
        )

    return vals


def compute_payroll_vals(applicant, employee):
    Employee = env['hr.employee'].sudo()
    employee_fields = Employee._fields
    applicant_fields = applicant._fields
    source_contract = get_source_employment_contract(applicant)

    vals = {}
    warnings = []

    date_start = False
    date_end = False
    wage = False
    contract_number = False

    if source_contract:
        sc_fields = source_contract._fields
        if 'x_contract_start_date' in sc_fields and source_contract.x_contract_start_date:
            date_start = source_contract.x_contract_start_date
        if 'x_contract_end_date' in sc_fields and source_contract.x_contract_end_date:
            date_end = source_contract.x_contract_end_date
        if 'x_monthly_wage_amount' in sc_fields and source_contract.x_monthly_wage_amount:
            wage = source_contract.x_monthly_wage_amount
        if 'x_contract_number' in sc_fields and source_contract.x_contract_number:
            contract_number = source_contract.x_contract_number

    if not date_start and 'x_handover_contract_date_start' in applicant_fields and applicant.x_handover_contract_date_start:
        date_start = applicant.x_handover_contract_date_start
    if not date_start and 'x_employment_contract_start_date' in applicant_fields and applicant.x_employment_contract_start_date:
        date_start = applicant.x_employment_contract_start_date
    if not date_start and 'availability' in applicant_fields and applicant.availability:
        date_start = applicant.availability
    if not date_start:
        date_start = datetime.date.today()
        warnings.append('لم يتم العثور على تاريخ بداية عقد مؤكد؛ تم استخدام تاريخ اليوم كقيمة تشغيلية مؤقتة.')

    if not date_end and 'x_handover_contract_date_end' in applicant_fields and applicant.x_handover_contract_date_end:
        date_end = applicant.x_handover_contract_date_end
    if not date_end and 'x_employment_contract_end_date' in applicant_fields and applicant.x_employment_contract_end_date:
        date_end = applicant.x_employment_contract_end_date

    if not wage and 'x_handover_wage' in applicant_fields and applicant.x_handover_wage:
        wage = applicant.x_handover_wage
    if not wage and 'x_employment_contract_monthly_wage' in applicant_fields and applicant.x_employment_contract_monthly_wage:
        wage = applicant.x_employment_contract_monthly_wage
    if not wage:
        wage = 0.0
        warnings.append('لم يتم العثور على قيمة راتب شهرية؛ تم ضبط الأجر على 0.0 مؤقتاً ويجب على الموارد البشرية/الرواتب مراجعته.')

    for start_field in ['contract_date_start', 'date_start']:
        if start_field in employee_fields:
            vals[start_field] = date_start
            break

    for end_field in ['contract_date_end', 'date_end']:
        if date_end and end_field in employee_fields:
            vals[end_field] = date_end
            break

    if 'wage' in employee_fields:
        vals['wage'] = wage

    wage_type = False
    if 'x_handover_wage_type' in applicant_fields and applicant.x_handover_wage_type:
        wage_type = applicant.x_handover_wage_type
    if not wage_type:
        wage_type = 'monthly'
    if 'wage_type' in employee_fields and selection_contains(Employee, 'wage_type', wage_type):
        vals['wage_type'] = wage_type

    work_entry_source = False
    if 'x_handover_work_entry_source' in applicant_fields and applicant.x_handover_work_entry_source:
        work_entry_source = applicant.x_handover_work_entry_source
    if not work_entry_source:
        work_entry_source = 'calendar'
    if 'work_entry_source' in employee_fields and selection_contains(Employee, 'work_entry_source', work_entry_source):
        vals['work_entry_source'] = work_entry_source

    resource_calendar = False
    if 'x_handover_resource_calendar_id' in applicant_fields and applicant.x_handover_resource_calendar_id:
        resource_calendar = applicant.x_handover_resource_calendar_id
    if not resource_calendar:
        resource_calendar = find_first('resource.calendar', [
            [('name', '=', 'Standard 40 hours/week'), ('company_id', 'in', [env.company.id, False])],
            [('name', 'ilike', 'Standard 40'), ('company_id', 'in', [env.company.id, False])],
            [('company_id', 'in', [env.company.id, False])],
            [],
        ])
    if resource_calendar and 'resource_calendar_id' in employee_fields:
        vals['resource_calendar_id'] = resource_calendar.id
    elif 'resource_calendar_id' in employee_fields:
        warnings.append('لم يتم العثور على جدول عمل افتراضي مناسب للموظف.')

    contract_type = False
    if 'x_handover_contract_type_id' in applicant_fields and applicant.x_handover_contract_type_id:
        contract_type = applicant.x_handover_contract_type_id
    if not contract_type:
        contract_type = find_first('hr.contract.type', [
            [('name', '=', 'Employee')],
            [('name', '=', 'Full-Time')],
            [('name', '=', 'Permanent')],
            [],
        ])
    if contract_type and 'contract_type_id' in employee_fields:
        vals['contract_type_id'] = contract_type.id

    structure_type = False
    if 'x_handover_structure_type_id' in applicant_fields and applicant.x_handover_structure_type_id:
        structure_type = applicant.x_handover_structure_type_id
    if not structure_type:
        structure_type = find_first('hr.payroll.structure.type', [
            [('name', '=', 'Fixed Month - Regular')],
            [('name', 'ilike', 'Fixed Month')],
            [('name', '=', 'Employee')],
            [],
        ])
    if structure_type and 'structure_type_id' in employee_fields:
        vals['structure_type_id'] = structure_type.id
    elif 'structure_type_id' in employee_fields:
        warnings.append('لم يتم العثور على فئة أجر/هيكل راتب افتراضي مناسب.')

    if 'employee_type' in employee_fields and selection_contains(Employee, 'employee_type', 'employee'):
        vals['employee_type'] = 'employee'

    if not contract_number and 'x_employment_contract_number' in applicant_fields and applicant.x_employment_contract_number:
        contract_number = applicant.x_employment_contract_number
    if contract_number:
        for ref_field in ['registration_number', 'contract_reference', 'reference']:
            if ref_field in employee_fields:
                vals[ref_field] = contract_number
                break

    return vals, warnings, source_contract


def sync_employee_payroll(applicant, employee):
    prepare_applicant_payroll_defaults(applicant)
    payroll_vals, warnings, source_contract = compute_payroll_vals(applicant, employee)

    if payroll_vals:
        employee.write(payroll_vals)

    if source_contract:
        source_vals = {}
        if 'x_employee_id' in source_contract._fields:
            source_vals['x_employee_id'] = employee.id
        if source_vals:
            source_contract.write(source_vals)

    notes = []
    if payroll_vals:
        notes.append('تم تحديث حقول الرواتب/العقد على سجل الموظف: %s.' % ', '.join(sorted(payroll_vals.keys())))
    else:
        notes.append('لم توجد حقول رواتب/عقد قابلة للتحديث على سجل الموظف في هذه القاعدة.')

    if warnings:
        notes.append('تنبيهات: %s' % ' | '.join(warnings))

    payroll_ready = bool(payroll_vals) and not warnings
    note = ' '.join(notes)
    write_payroll_status(applicant, payroll_ready, note)
    employee.message_post(body=note)

    return payroll_ready, note


def accepted_bank_submission(applicant):
    try:
        Submission = env['x_hr.applicant_required_document_submission'].sudo()
    except Exception:
        return False

    fields = Submission._fields
    domain = []

    if 'x_applicant_id' in fields:
        domain.append(('x_applicant_id', '=', applicant.id))
    else:
        return False

    if 'x_state' in fields:
        domain.append(('x_state', '=', 'accepted'))

    if 'x_document_code' in fields:
        domain.append(('x_document_code', 'in', ['bank_information', 'bank_account', 'bank']))
    elif 'x_document_type' in fields:
        domain.append(('x_document_type', 'in', ['bank_information', 'bank_account', 'bank']))

    order_parts = []
    for f in ['x_reviewed_on', 'x_submitted_on', 'write_date', 'create_date']:
        if f in fields:
            order_parts.append('%s desc' % f)
    order_parts.append('id desc')

    try:
        return Submission.search(domain, order=', '.join(order_parts), limit=1)
    except Exception:
        return False


def clean_bank_text(value):
    if not value:
        return False
    value = str(value).strip()
    return value or False


def compact_account(value):
    value = clean_bank_text(value)
    if not value:
        return False
    return ''.join(value.split())


def read_first_field(record, field_names):
    if not record:
        return False
    fields = record._fields
    for field_name in field_names:
        if field_name in fields and record[field_name]:
            return record[field_name]
    return False


def get_bank_source_data(applicant):
    source_contract = get_source_employment_contract(applicant)
    bank_submission = accepted_bank_submission(applicant)

    bank_name = read_first_field(source_contract, ['x_bank_name', 'x_bank'])
    bank_branch = read_first_field(source_contract, ['x_bank_branch', 'x_branch'])
    account_number = read_first_field(source_contract, ['x_bank_account_number', 'x_account_number'])
    iban = read_first_field(source_contract, ['x_iban', 'x_bank_iban', 'x_iban_number', 'x_bank_account_iban'])
    source_attachment = read_first_field(source_contract, ['x_bank_source_attachment_id', 'x_bank_attachment_id'])

    if bank_submission:
        bank_name = bank_name or read_first_field(bank_submission, ['x_bank_name', 'x_bank'])
        bank_branch = bank_branch or read_first_field(bank_submission, ['x_bank_branch', 'x_branch'])
        account_number = account_number or read_first_field(bank_submission, ['x_bank_account_number', 'x_account_number'])
        iban = iban or read_first_field(bank_submission, ['x_iban', 'x_bank_iban', 'x_iban_number', 'x_bank_account_iban'])
        source_attachment = source_attachment or read_first_field(bank_submission, ['x_attachment_id', 'x_bank_source_attachment_id', 'x_bank_attachment_id'])

    return {
        'source_contract': source_contract,
        'bank_submission': bank_submission,
        'bank_name': clean_bank_text(bank_name),
        'bank_branch': clean_bank_text(bank_branch),
        'account_number': compact_account(account_number),
        'iban': compact_account(iban),
        'source_attachment': source_attachment,
    }


def write_bank_status(applicant, bank_ready, bank_account, notes):
    vals = {}
    mapping = {
        'x_employment_bank_ready': bool(bank_ready),
        'x_employment_partner_bank_id': bank_account.id if bank_account else False,
        'x_employment_bank_checked_on': datetime.datetime.now(),
        'x_employment_bank_checked_by_user_id': env.user.id,
        'x_employment_bank_notes': notes or False,
    }
    for field_name, value in mapping.items():
        if field_name in applicant._fields:
            vals[field_name] = value
    if vals:
        applicant.write(vals)


def resolve_bank_partner(applicant, employee):
    employee_fields = employee._fields

    partner = False

    # Payroll Bank Accounts domain is partner_id = employee.work_contact_id.
    # Prefer work_contact_id so the bank account appears in the employee Personal tab.
    if 'work_contact_id' in employee_fields and employee.work_contact_id:
        partner = employee.work_contact_id

    if not partner and 'partner_id' in applicant._fields and applicant.partner_id:
        partner = applicant.partner_id

    if not partner and 'user_id' in employee_fields and employee.user_id and employee.user_id.partner_id:
        partner = employee.user_id.partner_id

    if not partner:
        partner_vals = {
            'name': employee.name or applicant.partner_name or applicant.display_name or 'Employee',
        }

        email_value = False
        for field_name in ['work_email', 'private_email']:
            if field_name in employee_fields and employee[field_name]:
                email_value = employee[field_name]
                break
        if email_value:
            partner_vals['email'] = email_value

        phone_value = False
        for field_name in ['mobile_phone', 'work_phone', 'private_phone']:
            if field_name in employee_fields and employee[field_name]:
                phone_value = employee[field_name]
                break
        if phone_value:
            partner_vals['phone'] = phone_value

        partner = env['res.partner'].sudo().create(partner_vals)

    # Ensure the employee work contact points to the partner used by payroll bank accounts.
    if partner and 'work_contact_id' in employee_fields:
        try:
            if not employee.work_contact_id or employee.work_contact_id.id != partner.id:
                employee.write({'work_contact_id': partner.id})
        except Exception:
            pass

    # Private address can remain separately managed; do not use it as the primary bank partner.
    return partner


def copy_bank_attachment_to_employee(source_attachment, employee):
    if not source_attachment:
        return False
    try:
        return source_attachment.sudo().copy({
            'name': 'Bank proof - %s' % (source_attachment.name or employee.name or 'employee'),
            'res_model': 'hr.employee',
            'res_id': employee.id,
        })
    except Exception:
        return False


def sync_employee_bank_account(applicant, employee):
    bank_data = get_bank_source_data(applicant)
    account_number = bank_data.get('account_number')
    iban = bank_data.get('iban')
    bank_name = bank_data.get('bank_name')
    bank_branch = bank_data.get('bank_branch')
    source_contract = bank_data.get('source_contract')
    bank_submission = bank_data.get('bank_submission')
    source_attachment = bank_data.get('source_attachment')

    if not account_number and not iban:
        note = 'لا توجد بيانات حساب مصرفي مقبولة لهذا المتقدم حتى الآن. لم يتم إنشاء حساب بنكي للموظف.'
        write_bank_status(applicant, False, False, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, False, note

    PartnerBank = env['res.partner.bank'].sudo()
    bank_fields = PartnerBank._fields
    employee_fields = employee._fields

    if 'account_number' not in bank_fields:
        note = 'لا يمكن إنشاء الحساب البنكي لأن نموذج res.partner.bank لا يحتوي على الحقل account_number في هذه القاعدة.'
        write_bank_status(applicant, False, False, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, False, note

    partner = resolve_bank_partner(applicant, employee)
    bank_account = False

    if source_contract and 'x_partner_bank_id' in source_contract._fields and source_contract.x_partner_bank_id:
        bank_account = source_contract.x_partner_bank_id.sudo()

    if not bank_account:
        search_domains = []

        if account_number:
            domain = [('account_number', '=', account_number)]
            if partner and 'partner_id' in bank_fields:
                domain.append(('partner_id', '=', partner.id))
            search_domains.append(domain)

        if iban and 'x_iban' in bank_fields:
            domain = [('x_iban', '=', iban)]
            if partner and 'partner_id' in bank_fields:
                domain.append(('partner_id', '=', partner.id))
            search_domains.append(domain)

        for domain in search_domains:
            try:
                bank_account = PartnerBank.search(domain, limit=1)
            except Exception:
                bank_account = False
            if bank_account:
                break

    bank_vals = {
        'account_number': account_number or iban,
    }

    if partner and 'partner_id' in bank_fields:
        bank_vals['partner_id'] = partner.id

    if 'holder_name' in bank_fields:
        bank_vals['holder_name'] = employee.name or applicant.partner_name or applicant.display_name

    if bank_name and 'bank_name' in bank_fields:
        bank_vals['bank_name'] = bank_name

    if bank_branch and 'city' in bank_fields:
        bank_vals['city'] = bank_branch

    if iban and 'x_iban' in bank_fields:
        bank_vals['x_iban'] = iban

    if bank_name and 'x_bank_name_snapshot' in bank_fields:
        bank_vals['x_bank_name_snapshot'] = bank_name

    if bank_branch and 'x_bank_branch_snapshot' in bank_fields:
        bank_vals['x_bank_branch_snapshot'] = bank_branch

    if 'x_source_applicant_id' in bank_fields:
        bank_vals['x_source_applicant_id'] = applicant.id

    if source_contract and 'x_source_applicant_employment_contract_id' in bank_fields:
        bank_vals['x_source_applicant_employment_contract_id'] = source_contract.id

    if bank_submission and 'x_source_required_document_submission_id' in bank_fields:
        bank_vals['x_source_required_document_submission_id'] = bank_submission.id

    if source_attachment and 'x_source_bank_attachment_id' in bank_fields:
        bank_vals['x_source_bank_attachment_id'] = source_attachment.id

    # Finance payment trust remains a later control; this action only creates/links the bank account.

    try:
        if bank_account:
            bank_account.write(bank_vals)
            created = False
        else:
            bank_account = PartnerBank.create(bank_vals)
            created = True
    except Exception as e:
        note = 'تعذر إنشاء/تحديث الحساب البنكي الأصلي للموظف: %s' % str(e)
        write_bank_status(applicant, False, False, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, False, note

    link_warnings = []

    if 'bank_account_ids' in employee_fields:
        try:
            if bank_account.id not in employee.bank_account_ids.ids:
                employee.write({'bank_account_ids': [(4, bank_account.id)]})
        except Exception as e:
            link_warnings.append('تعذر ربط الحساب عبر bank_account_ids: %s' % str(e))

    for field_name in ['primary_bank_account_id', 'bank_account_id']:
        if field_name in employee_fields:
            try:
                if not employee[field_name] or employee[field_name].id != bank_account.id:
                    employee.write({field_name: bank_account.id})
            except Exception as e:
                link_warnings.append('تعذر ضبط %s: %s' % (field_name, str(e)))

    if source_contract:
        source_vals = {}
        if 'x_partner_bank_id' in source_contract._fields:
            source_vals['x_partner_bank_id'] = bank_account.id
        if source_vals:
            source_contract.write(source_vals)

    copied_attachment = copy_bank_attachment_to_employee(source_attachment, employee)

    if created:
        phrase = 'تم إنشاء حساب بنكي أصلي للموظف وربطه بسجل الموظف.'
    else:
        phrase = 'تم العثور على حساب بنكي أصلي قائم وتحديثه وربطه بسجل الموظف.'

    detail_parts = [phrase]

    if iban:
        detail_parts.append('تم حفظ IBAN في الحقل المخصص على حساب البنك.')

    if copied_attachment:
        detail_parts.append('تم نسخ مرفق إثبات الحساب البنكي إلى سجل الموظف.')

    if link_warnings:
        detail_parts.append('تنبيهات الربط: %s' % ' | '.join(link_warnings))

    note = ' '.join(detail_parts)
    bank_ready = bool(bank_account) and not link_warnings
    write_bank_status(applicant, bank_ready, bank_account, note)

    applicant.message_post(body=note)
    if copied_attachment:
        employee.message_post(body=note, attachment_ids=[copied_attachment.id])
    else:
        employee.message_post(body=note)

    if 'message_ids' in bank_fields:
        try:
            bank_account.message_post(body='تم إنشاء/تحديث هذا الحساب البنكي من المتقدم: %s.' % (applicant.partner_name or applicant.display_name))
        except Exception:
            pass

    return bank_ready, bank_account, note


def write_artifact_status(applicant, ready, count, notes):
    vals = {}
    mapping = {
        'x_employment_artifacts_ready': bool(ready),
        'x_employment_artifacts_count': int(count or 0),
        'x_employment_artifacts_checked_on': datetime.datetime.now(),
        'x_employment_artifacts_checked_by_user_id': env.user.id,
        'x_employment_artifacts_notes': notes or False,
    }
    for field_name, value in mapping.items():
        if field_name in applicant._fields:
            vals[field_name] = value
    if vals:
        applicant.write(vals)


def attachment_from(record, field_names):
    if not record:
        return False
    fields = record._fields
    for field_name in field_names:
        if field_name in fields and record[field_name]:
            return record[field_name]
    return False


def append_artifact(artifacts, attachment, label, kind):
    if not attachment:
        return
    if not attachment.id:
        return
    existing_ids = [a['attachment'].id for a in artifacts]
    if attachment.id in existing_ids:
        return
    artifacts.append({
        'attachment': attachment.sudo(),
        'label': label,
        'kind': kind,
    })


def collect_employment_artifacts(applicant):
    artifacts = []

    source_contract = get_source_employment_contract(applicant)

    if source_contract:
        # F-0005 employment contract artifacts. Prefer signed/accredited official copies.
        append_artifact(
            artifacts,
            attachment_from(source_contract, ['x_signed_attachment_id', 'x_signed_pdf_attachment_id']),
            'F-0005 signed employment contract',
            'f0005_signed_contract',
        )
        append_artifact(
            artifacts,
            attachment_from(source_contract, ['x_ministry_accredited_attachment_id', 'x_accredited_attachment_id', 'x_ministry_attachment_id']),
            'F-0005 ministry accredited employment contract',
            'f0005_ministry_accredited_contract',
        )
        append_artifact(
            artifacts,
            attachment_from(source_contract, ['x_signature_certificate_attachment_id', 'x_sign_certificate_attachment_id', 'x_certificate_attachment_id']),
            'F-0005 signing certificate',
            'f0005_signature_certificate',
        )

    # F-0006 TOR artifacts may live directly on hr.applicant.
    append_artifact(
        artifacts,
        attachment_from(applicant, ['x_tor_signed_attachment_id', 'x_tor_signed_pdf_attachment_id', 'x_tor_final_attachment_id']),
        'F-0006 signed TOR',
        'f0006_signed_tor',
    )
    append_artifact(
        artifacts,
        attachment_from(applicant, ['x_tor_signature_certificate_attachment_id', 'x_tor_certificate_attachment_id', 'x_tor_sign_certificate_attachment_id']),
        'F-0006 signing certificate',
        'f0006_signature_certificate',
    )

    # Applicant declarations: F-0004, F-0007, F-0009 where present.
    try:
        Declaration = env['x_hr.applicant_declaration'].sudo()
        dec_fields = Declaration._fields
        domain = []
        if 'x_applicant_id' in dec_fields:
            domain.append(('x_applicant_id', '=', applicant.id))
        if 'x_state' in dec_fields:
            domain.append(('x_state', '=', 'signed'))
        declarations = Declaration.search(domain, order='id asc') if domain else Declaration.browse()
    except Exception:
        declarations = False

    for declaration in declarations:
        code = False
        for code_field in ['x_declaration_code', 'x_document_code', 'x_template_code']:
            if code_field in declaration._fields and declaration[code_field]:
                code = declaration[code_field]
                break

        name = False
        for name_field in ['x_name', 'display_name']:
            if name_field in declaration._fields and declaration[name_field]:
                name = declaration[name_field]
                break

        label_prefix = code or name or 'Applicant declaration'

        append_artifact(
            artifacts,
            attachment_from(declaration, ['x_signed_attachment_id', 'x_signed_pdf_attachment_id']),
            '%s signed declaration' % label_prefix,
            '%s_signed_declaration' % str(label_prefix).lower().replace(' ', '_'),
        )
        append_artifact(
            artifacts,
            attachment_from(declaration, ['x_signature_certificate_attachment_id', 'x_sign_certificate_attachment_id', 'x_certificate_attachment_id']),
            '%s signing certificate' % label_prefix,
            '%s_signature_certificate' % str(label_prefix).lower().replace(' ', '_'),
        )

    return artifacts


def copy_artifact_to_employee(applicant, employee, artifact):
    source_attachment = artifact.get('attachment')
    label = artifact.get('label') or 'Employment artifact'
    kind = artifact.get('kind') or 'employment_artifact'

    if not source_attachment:
        return False, False

    Attachment = env['ir.attachment'].sudo()
    attachment_fields = Attachment._fields

    duplicate = False
    if 'x_source_employment_attachment_id' in attachment_fields:
        duplicate = Attachment.search([
            ('res_model', '=', 'hr.employee'),
            ('res_id', '=', employee.id),
            ('x_source_employment_attachment_id', '=', source_attachment.id),
        ], limit=1)

    if not duplicate:
        duplicate = Attachment.search([
            ('res_model', '=', 'hr.employee'),
            ('res_id', '=', employee.id),
            ('name', '=', source_attachment.name),
        ], limit=1)

    if duplicate:
        return duplicate, False

    copy_name = source_attachment.name or label
    vals = {
        'name': copy_name,
        'res_model': 'hr.employee',
        'res_id': employee.id,
    }

    if 'x_source_employment_attachment_id' in attachment_fields:
        vals['x_source_employment_attachment_id'] = source_attachment.id
    if 'x_source_employment_applicant_id' in attachment_fields:
        vals['x_source_employment_applicant_id'] = applicant.id
    if 'x_employment_handover_kind' in attachment_fields:
        vals['x_employment_handover_kind'] = kind

    copied = source_attachment.copy(vals)
    return copied, True


def sync_employee_artifacts(applicant, employee):
    artifacts = collect_employment_artifacts(applicant)

    if not artifacts:
        note = 'لم يتم العثور على مرفقات رسمية/موقعة جاهزة للترحيل إلى سجل الموظف.'
        write_artifact_status(applicant, False, 0, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, [], note

    copied_ids = []
    existing_ids = []
    labels = []

    for artifact in artifacts:
        copied, created = copy_artifact_to_employee(applicant, employee, artifact)
        if not copied:
            continue
        labels.append(artifact.get('label') or copied.name)
        if created:
            copied_ids.append(copied.id)
        else:
            existing_ids.append(copied.id)

    all_ids = copied_ids + existing_ids

    if not all_ids:
        note = 'تم العثور على مرفقات للترحيل، لكن لم يتم نسخ أي مرفق إلى سجل الموظف.'
        write_artifact_status(applicant, False, 0, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, [], note

    note = 'تم ترحيل/تأكيد مرفقات ما قبل التوظيف إلى سجل الموظف: %s.' % ', '.join(labels)
    if existing_ids:
        note += ' تم تجاهل النسخ المكررة الموجودة مسبقاً.'

    write_artifact_status(applicant, True, len(all_ids), note)
    applicant.message_post(body=note)

    # Attach only newly copied files to the chatter message to avoid noisy duplicates.
    if copied_ids:
        employee.message_post(body=note, attachment_ids=copied_ids)
    else:
        employee.message_post(body=note)

    return True, all_ids, note


def write_final_handover_status(applicant, closed, stage_moved, notes):
    vals = {}
    mapping = {
        'x_employment_handover_closed': bool(closed),
        'x_employment_stage_move_done': bool(stage_moved),
        'x_employment_handover_closure_notes': notes or False,
    }

    if closed:
        mapping['x_employment_handover_closed_on'] = datetime.datetime.now()
        mapping['x_employment_handover_closed_by_user_id'] = env.user.id

    for field_name, value in mapping.items():
        if field_name in applicant._fields:
            vals[field_name] = value

    if vals:
        applicant.write(vals)


def final_handover_missing_items(applicant):
    missing = []

    if 'x_employment_employee_id' in applicant._fields:
        if not applicant.x_employment_employee_id:
            missing.append('سجل الموظف المرتبط')
    else:
        missing.append('حقل ربط الموظف')

    if 'x_employment_payroll_ready' in applicant._fields and not applicant.x_employment_payroll_ready:
        missing.append('جاهزية الرواتب/العقد')

    if 'x_employment_bank_ready' in applicant._fields and not applicant.x_employment_bank_ready:
        missing.append('جاهزية الحساب البنكي')

    if 'x_employment_artifacts_ready' in applicant._fields and not applicant.x_employment_artifacts_ready:
        missing.append('جاهزية المرفقات الرسمية')

    return missing


def find_contract_signed_stage(applicant):
    try:
        Stage = env['hr.recruitment.stage'].sudo()
    except Exception:
        return False

    stage_fields = Stage._fields

    stage_domains = [
        [('name', '=', 'Contract Signed')],
        [('name', 'ilike', 'Contract Signed')],
        [('name', 'ilike', 'Signed')],
        [('name', 'ilike', 'توقيع')],
        [('name', 'ilike', 'موقع')],
        [('name', 'ilike', 'تم توقيع')],
    ]

    base_domains = [[]]

    if 'job_ids' in stage_fields and 'job_id' in applicant._fields and applicant.job_id:
        base_domains.insert(0, ['|', ('job_ids', '=', False), ('job_ids', 'in', [applicant.job_id.id])])

    for base_domain in base_domains:
        for stage_domain in stage_domains:
            try:
                stage = Stage.search(stage_domain + base_domain, order='sequence asc, id asc', limit=1)
            except Exception:
                stage = False
            if stage:
                return stage

    return False


def move_applicant_to_contract_signed(applicant):
    if 'stage_id' not in applicant._fields:
        return False, 'لا يمكن تحديث مرحلة المتقدم لأن الحقل stage_id غير متاح.'

    target_stage = find_contract_signed_stage(applicant)
    if not target_stage:
        return False, 'لم يتم العثور على مرحلة Contract Signed / تم توقيع العقد. تم ترك مرحلة المتقدم بدون تغيير.'

    if applicant.stage_id and applicant.stage_id.id == target_stage.id:
        return True, 'المتقدم موجود بالفعل في مرحلة توقيع العقد/Contract Signed.'

    old_stage_name = applicant.stage_id.name if applicant.stage_id else 'بدون مرحلة'
    applicant.write({'stage_id': target_stage.id})
    return True, 'تم نقل المتقدم من مرحلة %s إلى مرحلة %s.' % (old_stage_name, target_stage.name)


def finalize_employment_handover(applicant, employee):
    missing = final_handover_missing_items(applicant)

    if missing:
        note = 'لم يتم إغلاق ترحيل التوظيف نهائياً بسبب النواقص التالية: %s.' % ', '.join(missing)
        write_final_handover_status(applicant, False, False, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return False, note

    stage_moved, stage_note = move_applicant_to_contract_signed(applicant)

    if stage_moved:
        note = 'تم إغلاق ترحيل المتقدم إلى الموظف بنجاح. %s' % stage_note
        write_final_handover_status(applicant, True, True, note)
        applicant.message_post(body=note)
        employee.message_post(body=note)
        return True, note

    note = 'اكتملت بيانات الترحيل الأساسية، لكن لم يتم إغلاق الترحيل نهائياً بسبب مرحلة المتقدم: %s' % stage_note
    write_final_handover_status(applicant, False, False, note)
    applicant.message_post(body=note)
    employee.message_post(body=note)
    return False, note


applicant = records.sudo()[:1]

if not applicant:
    action = toast('لا يوجد متقدم', 'افتح سجل متقدم أولاً.', 'warning')
else:
    gate_ready = bool(
        'x_preboarding_gate_ready' in applicant._fields
        and applicant.x_preboarding_gate_ready
    )
    gate_state = applicant.x_preboarding_gate_state if 'x_preboarding_gate_state' in applicant._fields else False

    if not gate_ready or gate_state != 'ready':
        missing = applicant.x_preboarding_gate_missing_summary if 'x_preboarding_gate_missing_summary' in applicant._fields else False
        if not missing:
            missing = 'يرجى تشغيل تحديث جاهزية التوظيف والتأكد من اكتمال قرار التعيين، العقد، الوصف الوظيفي، F-0007، وF-0009.'

        note = 'لا يمكن بدء التوظيف لأن جاهزية التوظيف غير مكتملة. المتبقي/المطلوب: %s' % missing
        write_handover(applicant, 'blocked', False, note)
        applicant.message_post(body=note)
        action = toast('لا يمكن بدء التوظيف', note, 'warning', True, reload_applicant(applicant))
    else:
        Employee = env['hr.employee'].sudo()
        employee_fields = Employee._fields
        applicant_fields = applicant._fields

        existing_employee = False

        if 'x_employment_employee_id' in applicant_fields and applicant.x_employment_employee_id:
            existing_employee = applicant.x_employment_employee_id.sudo()

        if not existing_employee and 'x_source_applicant_id' in employee_fields:
            existing_employee = Employee.search([
                ('x_source_applicant_id', '=', applicant.id),
            ], limit=1)

        employee_vals, national_id_value = compute_employee_vals(applicant, existing_employee)

        if not existing_employee and national_id_value and 'identification_id' in employee_fields:
            duplicate_employees = Employee.search([
                ('identification_id', '=', national_id_value),
            ], limit=2)
            if len(duplicate_employees) == 1:
                note = 'تم العثور على موظف حالي بنفس الرقم الوطني/التعريفي. لم يتم إنشاء موظف جديد لتجنب التكرار. يرجى مراجعة الموظف الحالي وربطه يدوياً إذا كان هو نفس الشخص.'
                write_handover(applicant, 'blocked', False, note)
                applicant.message_post(body=note)
                action = toast('احتمال تكرار موظف', note, 'warning', True, reload_applicant(applicant))
            elif len(duplicate_employees) > 1:
                note = 'تم العثور على أكثر من موظف بنفس الرقم الوطني/التعريفي. لا يمكن بدء التوظيف آلياً قبل تنظيف التكرارات.'
                write_handover(applicant, 'blocked', False, note)
                applicant.message_post(body=note)
                action = toast('تكرار بيانات موظفين', note, 'danger', True, reload_applicant(applicant))

        if not action:
            if existing_employee:
                employee = existing_employee

                sync_vals = dict(employee_vals)
                if sync_vals:
                    employee.write(sync_vals)

                link_vals = {}
                if 'x_employment_employee_id' in applicant_fields and applicant.x_employment_employee_id.id != employee.id:
                    link_vals['x_employment_employee_id'] = employee.id
                if 'x_employment_employee_created_on' in applicant_fields and not applicant.x_employment_employee_created_on:
                    link_vals['x_employment_employee_created_on'] = datetime.datetime.now()
                if 'x_employment_employee_created_by_user_id' in applicant_fields and not applicant.x_employment_employee_created_by_user_id:
                    link_vals['x_employment_employee_created_by_user_id'] = env.user.id
                if link_vals:
                    applicant.write(link_vals)

                payroll_ready, payroll_note = sync_employee_payroll(applicant, employee)
                bank_ready, bank_account, bank_note = sync_employee_bank_account(applicant, employee)
                artifacts_ready, artifact_ids, artifact_note = sync_employee_artifacts(applicant, employee)
                final_ready, final_note = finalize_employment_handover(applicant, employee)

                note = 'تم ربط الموظف. تم العثور على سجل موظف مرتبط بهذا المتقدم، ولم يتم إنشاء موظف جديد. تم تحديث جاهزية الرواتب/العقد على سجل الموظف. تم تنفيذ فحص الإغلاق النهائي ونقل المرحلة عند اكتمال الشروط.'
                note = '%s %s' % (note, final_note)
                write_handover(applicant, 'onboarded', True, note)
                applicant.message_post(body=note)
                employee.message_post(body='تم تأكيد الربط والتحديث من المتقدم: %s.' % (applicant.partner_name or applicant.display_name))
                action = toast('تم ربط الموظف وتحديث الرواتب', note, 'success', False, reload_applicant(applicant))
            else:
                employee = Employee.create(employee_vals)

                applicant_vals = {}
                if 'x_employment_employee_id' in applicant_fields:
                    applicant_vals['x_employment_employee_id'] = employee.id
                if 'x_employment_employee_created_on' in applicant_fields:
                    applicant_vals['x_employment_employee_created_on'] = datetime.datetime.now()
                if 'x_employment_employee_created_by_user_id' in applicant_fields:
                    applicant_vals['x_employment_employee_created_by_user_id'] = env.user.id
                if applicant_vals:
                    applicant.write(applicant_vals)

                payroll_ready, payroll_note = sync_employee_payroll(applicant, employee)
                bank_ready, bank_account, bank_note = sync_employee_bank_account(applicant, employee)
                artifacts_ready, artifact_ids, artifact_note = sync_employee_artifacts(applicant, employee)
                final_ready, final_note = finalize_employment_handover(applicant, employee)

                note = 'تم إنشاء سجل الموظف وربطه بالمتقدم. تم تحديث جاهزية الرواتب/العقد على سجل الموظف. تم ترحيل/تأكيد المرفقات الرسمية حيثما توفرت. تم تنفيذ فحص الإغلاق النهائي ونقل المرحلة عند اكتمال الشروط.'
                note = '%s %s' % (note, final_note)
                write_handover(applicant, 'onboarded', True, note)
                applicant.message_post(body=note)
                employee.message_post(body='تم إنشاء هذا الموظف من المتقدم: %s.' % (applicant.partner_name or applicant.display_name))
                action = toast('تم إنشاء الموظف وتحديث الرواتب', note, 'success', False, reload_applicant(applicant))

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
